# ============================================================
# MAIN FUNCTION
# ============================================================
def generate_meanings(chart_data):
    """Generate static meanings for all chart placements."""
    planets = chart_data.get("planets_data", [])
    houses = chart_data.get("houses_data", [])
    aspects = chart_data.get("planetary_aspects", [])

    # Map planet names to house lordship
    sign_to_lord = {
        "Aries": "Mars", "Taurus": "Venus", "Gemini": "Mercury", "Cancer": "Moon",
        "Leo": "Sun", "Virgo": "Mercury", "Libra": "Venus", "Scorpio": "Mars",
        "Sagittarius": "Jupiter", "Capricorn": "Saturn", "Aquarius": "Saturn", "Pisces": "Jupiter"
    }

    # Find which house each planet lords over
    planet_lord_of = {}
    for h in houses:
        rasi = h.get("Rasi", "")
        lord = sign_to_lord.get(rasi, "")
        if lord:
            planet_lord_of[lord] = h.get("HouseNr", 0)

    # Build planet meanings
    planet_meanings = {}
    for p in planets:
        name = p.get("Object", "")
        rasi = p.get("Rasi", "")
        house_nr = p.get("HouseNr", 0)
        is_retro = p.get("isRetroGrade")

        entry = {
            "sign": rasi,
            "house": house_nr,
            "sign_meaning": PLANET_IN_SIGN.get(f"{name}_{rasi}", None),
            "house_meaning": PLANET_IN_HOUSE.get(f"{name}_{house_nr}", None),
            "retrograde": None,
            "lord_of": planet_lord_of.get(name, None),
            "lordship_meaning": None,
        }

        if is_retro:
            entry["retrograde"] = RETROGRADE_EFFECTS.get(f"{name}_R", None)

        lord_house = planet_lord_of.get(name)
        if lord_house:
            # When this planet is lord of house X, it brings its energy to that house
            entry["lordship_meaning"] = {
                "house": lord_house,
                "meaning": f"As lord of House {lord_house}, {name} brings its energy to matters of {', '.join(HOUSE_MEANINGS.get(str(lord_house), {}).get('areas', ['that area']))}.",
            }

        planet_meanings[name] = entry

    # Build house meanings
    house_meanings = {}
    for h in houses:
        hnr = str(h.get("HouseNr", 0))
        rasi = h.get("Rasi", "")
        nakshatra = h.get("Nakshatra", "")

        # Find planets in this house
        planets_in = [p.get("Object", "") for p in planets if p.get("HouseNr") == h.get("HouseNr")]

        house_meanings[hnr] = {
            "rasi": rasi,
            "rasi_lord": sign_to_lord.get(rasi, ""),
            "nakshatra": nakshatra,
            "house_meaning": HOUSE_MEANINGS.get(hnr, None),
            "nakshatra_meaning": NAKSHATRA_MEANINGS.get(resolve_nakshatra(nakshatra), None),
            "planets_in_house": planets_in,
        }

    # Build key aspect meanings (major aspects only, Vedic planets)
    vedic_planets = {"Sun", "Moon", "Mars", "Mercury", "Jupiter", "Venus", "Saturn", "Rahu", "Ketu"}
    major_types = {"Conjunction", "Opposition", "Trine", "Square", "Sextile"}
    seen_aspects = set()
    key_aspects = []

    for a in aspects:
        p1, p2 = a.get("P1", ""), a.get("P2", "")
        atype = a.get("AspectType", "")
        orb = a.get("AspectOrb", 99)

        if p1 not in vedic_planets or p2 not in vedic_planets:
            continue
        if atype not in major_types or orb > 8:
            continue

        pair_key = f"{min(p1,p2)}-{max(p1,p2)}-{atype}"
        if pair_key in seen_aspects:
            continue
        seen_aspects.add(pair_key)

        key_aspects.append({
            "P1": p1,
            "P2": p2,
            "AspectType": atype,
            "Orb": round(orb, 1),
            "meaning": f"{p1} {atype.lower()} {p2} — This {atype.lower()} creates a dynamic tension or harmony between {p1}'s energy and {p2}'s energy that shapes significant life patterns.",
        })

    return {
        "planet_meanings": planet_meanings,
        "house_meanings": house_meanings,
        "key_aspects": key_aspects,
    }


if __name__ == "__main__":
    input_data = json.loads(sys.stdin.read())
    chart_data = input_data.get("chart_data", {})
    result = generate_meanings(chart_data)
    print(json.dumps(result))
